// Generates src/tools/shared/_catalogs.generated.ts by reading machine-readable
// catalog JSON files from @sogni-ai/sogni-protocol and emitting them as inline
// TypeScript constants. Sibling to scripts/generate-openai-tools-manifests.mjs;
// kept separate so the catalog set evolves independently of the OpenAI tool
// manifests. Same rationale for inlining: Node ≥ 22 rejects bare JSON imports
// without `with { type: 'json' }`, which TypeScript cannot emit conditionally
// for dual CJS+ESM builds.
//
// The generated file is .gitignored. Run via `npm run codegen` or as part of
// `npm run build` / `npm install` (via `prepare`).
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

const require = createRequire(import.meta.url);
const protocolPkg = require.resolve('@sogni-ai/sogni-protocol/package.json');
const protocolCatalogsDir = join(dirname(protocolPkg), 'catalogs');

const outFile = join(process.cwd(), 'src', 'tools', 'shared', '_catalogs.generated.ts');

const catalogFiles = ['seedance-reference-limits.json'];

const constNameFor = (filename) => {
  const base = filename.replace(/\.json$/, '');
  // seedance-reference-limits → seedanceReferenceLimitsCatalog
  return `${base.replace(/[-_](.)/g, (_, ch) => ch.toUpperCase())}Catalog`;
};

const sections = [];
for (const file of catalogFiles) {
  const raw = await readFile(join(protocolCatalogsDir, file), 'utf8');
  // Validate JSON parses
  JSON.parse(raw);
  sections.push(`export const ${constNameFor(file)}: unknown = ${raw.trim()};`);
}

const banner = `// AUTO-GENERATED by scripts/generate-catalogs.mjs.
// Do not edit by hand. Re-run \`npm run codegen\` after changing the source
// JSON in @sogni-ai/sogni-protocol.
/* eslint-disable */
`;

await writeFile(outFile, `${banner}\n${sections.join('\n\n')}\n`, 'utf8');

console.log(`[generate-catalogs] wrote ${outFile} from @sogni-ai/sogni-protocol (${catalogFiles.length} catalogs)`);
